#!/usr/bin/env node
/**
 * Bundles assets/examples/** into src/core/examples.generated.ts.
 *
 * The plugin cannot read loose text files out of its own package at runtime,
 * so the example decks travel as string constants. Re-run after editing an
 * example deck: `node scripts/bundle-examples.js`. A unit test fails if the
 * generated file and the assets drift apart.
 */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..', 'assets', 'examples');
const out = path.join(__dirname, '..', 'src', 'core', 'examples.generated.ts');

function walk(dir) {
  return fs
    .readdirSync(dir, {withFileTypes: true})
    .sort((a, b) => a.name.localeCompare(b.name))
    .flatMap(e => (e.isDirectory() ? walk(path.join(dir, e.name)) : [path.join(dir, e.name)]));
}

const files = walk(root).map(f => ({
  path: path.relative(root, f).split(path.sep).join('/'),
  content: fs.readFileSync(f, 'utf8'),
}));

const body =
  '// Generated by scripts/bundle-examples.js from assets/examples. Do not edit by hand.\n' +
  "import type {IncomingFile} from './library';\n\n" +
  'export const EXAMPLE_DECKS: IncomingFile[] = ' +
  JSON.stringify(files, null, 2) +
  ';\n';
fs.writeFileSync(out, body);
console.log(`Wrote ${files.length} example decks to ${path.relative(process.cwd(), out)}`);
